head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.mkt = "";
scwin.rsn = "";
scwin.agn = "";
scwin.gubun = "";
scwin.spac = "";
scwin.selVal = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function(e) {
    try {
        // 초기화함수
        scwin.init();

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92008.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

    scwin.mkt = $c.data.getParameter("mkt");
    scwin.rsn = $c.data.getParameter("rsn");
    scwin.agn = $c.data.getParameter("agn");
    scwin.gubun = $c.data.getParameter("gubun");
    scwin.spac = $c.data.getParameter("spac");

/*
    scwin.mkt = "2";
    scwin.rsn = "10";
    scwin.agn = "agn";
    scwin.gubun = "gubun";
    scwin.spac = "N";
 */
    if($c.util.isEmpty(scwin.spac)){
        scwin.spac = "N";
    }
    if(scwin.rsn === "10"){
        tbx_etc.show("");
        ipt_etc.show("")
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_coSnm_onkeydown
 * @description ibx_coSnm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ibx_coSnm_onkeydown = async function(e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92008.ibx_coSnm_onkeydown" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description img_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = async function (e) {
    try {
        // 조회 버튼 클릭
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92008.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92008.img_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function (e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92008.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description grd_IsuInst 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.setParam(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92008.grd_IsuInst_oncelldblclick" });
    }
};

/**
 * @method
 * @name sbx_lGubun_onchange
 * @description sbx_lGubun 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_lGubun_onchange = function (info) {
    try {
        scwin.selectLGubun(info.newValue);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92008.sbx_lGubun_onchange" });
    }
};

/**
 * @method
 * @name dlt_listRes_onaftercolumnfilterchange
 * @description dlt_listRes onaftercolumnfilterchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dlt_listRes_onaftercolumnfilterchange = function () {
    try {

        txb_TotCnt.setValue(dlt_listRes.getRowCount());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92008.dlt_listRes_onaftercolumnfilterchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기업목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();
    dma_searchReq.set("mkt", scwin.mkt);
    dma_searchReq.set("rsn", scwin.rsn);
    dma_searchReq.set("agn", scwin.agn);
    dma_searchReq.set("gubun", scwin.gubun);
    dma_searchReq.set("spac", scwin.spac);

    const sbmOptions = {
            id: "sbm_codeList",
            action: "/api/listing/common/code/listing-common-biz",
            method: "get",
            ref: "dma_searchReq",
            target: "dlt_listRes=body"
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_Detail_submitdone(sbmRtn);

};

/**
 * @method
 * @name sbm_Detail_submitdone
 * @description Detail 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_Detail_submitdone = function (e) {
    dlt_listRes.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dlt_listRes.getRowCount());
    scwin.setSelectBox();
    dlt_listRes.setColumnFilter({type:"func", colIndex:"code", key:scwin.setSelectFilter2, condition:"and"});
    scwin.selectLGubun(sbx_lGubun.getValue());
};

/**
 * @method
 * @name sbm_isurList_submitdone
 * @description isurList 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_isurList_submitdone = function (e) {
    dlt_listRes.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dlt_listRes.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dlt_listRes.removeAll();
    txb_TotCnt.setValue("0");
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dlt_listRes.getRowPosition();
    }

    let code = dlt_listRes.getCellData(v_Currow, "code");
    if(scwin.rsn === "10" && code.substr(2) === "99"){
        if($c.util.isEmpty(ipt_etc.getValue())){
            await $c.win.alert("기타사유를 입력하세요.");
            return;
        }else{
            dlt_listRes.setCellData(v_Currow, "name", ipt_etc.getValue());
        }
    }
    const res = dlt_listRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

/**
 * @method
 * @name setSelectBox
 * @description 사유 목록에서 대분류 코드(끝자리 00)를 뽑아 대분류 셀렉트박스 구성
 * @returns {void}
 * @hidden N
 */
scwin.setSelectBox = function(){
    let rowCnt = dlt_listRes.getRowCount();
    let selectJson = [];
    for(let i = 0, j = rowCnt; i < j; i++){
        let code = dlt_listRes.getCellData(i, "code");
        let name = dlt_listRes.getCellData(i, "name");
        if(code.substr(2) === "00" || code.substr(2) === "0000"){
            selectJson.push({"code": code.substr(0, 2), "name": name})
        }
    }
    dlt_sbxList.setJSON(selectJson, true);
};

/**
 * @method
 * @name setSelectFilter
 * @description 사유 목록 컬럼 필터 — 대분류 코드(끝자리 00)만 포함
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.setSelectFilter = function (cellData, tmpParam, rowIdx){

    if(cellData.substr(2) === "00" || cellData.substr(2) === "0000"){
        return true;
    }
    return false;   // true 인 경우 데이터에 포함, false 인 경우 데이터에서 제외
};

/**
 * @method
 * @name setSelectFilter2
 * @description 사유 목록 컬럼 필터(2차)
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.setSelectFilter2 = function (cellData, tmpParam, rowIdx){

    if(cellData.substr(2) !== "00" && cellData.substr(2) !== "0000"){
        return true;
    }
    return false;   // true 인 경우 데이터에 포함, false 인 경우 데이터에서 제외
};

/**
 * @method
 * @name selectLGubun
 * @description 대분류 선택값으로 사유 목록 컬럼 필터 적용
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.selectLGubun = function(val){
    dlt_listRes.clearFilter();
    scwin.selVal = val;
    dlt_listRes.setColumnFilter({type:"func", colIndex:"code", key:scwin.setSelectFilter3, condition:"and"});
};

/**
 * @method
 * @name setSelectFilter3
 * @description 사유 목록 컬럼 필터 — 선택 대분류(selVal)에 속한 코드만 포함
 * @param {*} cellData cellData
 * @param {*} tmpParam tmpParam
 * @param {*} rowIdx rowIdx
 * @returns {Boolean}
 * @hidden N
 */
scwin.setSelectFilter3 = function (cellData, tmpParam, rowIdx){
    if(cellData.substr(2) !== "00" && cellData.substr(2) !== "0000" && cellData.substr(0, 2) === scwin.selVal){
        return true;
    }
    return false;
};
